import json
from pathlib import Path
D=Path(__file__).resolve().parent
def read(p):return json.loads((D/p).read_text(encoding='utf8'))
def pc(x):return f'{100*x:.2f}'.replace('.',',')
def interval(p):
    a,b=p['deltas']['fs']['ci'];return f"[{pc(a)}; {pc(b)}]"
def describe(g,a,b):
    p=g['pairs'][a+' minus '+b]
    return f"{pc(p['deltas']['fs']['mean'])} п.п., 95% ДИ {interval(p)}, {p['fs_wins']} побед и {p['fs_losses']} поражений"
def table_line(title,key,g):
    v=g['means'][key];return f"| {title} | {v['hits']}/{g['q']} | {pc(v['hits']/g['q'])}% | {pc(v['coverage'])}% | {v['tokens']:.1f} |"
def main():
    g=read('test-results.json')['primary'];fit=read('fit-lock.json')
    counts=[read(f'geometry-{i}-lock.json') for i in range(8)]
    labels={'dense':'DenseFT', 'exact/exact':'Обучение exact, чтение exact','exact/append':'Обучение exact, чтение append','append/exact':'Обучение append, чтение exact','append/append':'Обучение append, чтение append','dual/both':'Обучение exact и шести разностей, чтение обоих состояний','dual/zero':'Та же модель, шесть разностей обнулены','r20/exact':'Прежняя модель R20 на exact','r20/append':'Прежняя модель R20 на append'}
    lines=['# Обучение модели поиска с учётом отозванных связей', '',
      'Если одна исходная строка впоследствии встречается у второго производителя, ранее приписанная ей связь data.feeds может потерять однозначность. В прежнем эксперименте постоянно растущий граф использовался с моделью, обученной на уже исправленном графе. Здесь обе политики получили собственное обучение. Проверяется, может ли модель компенсировать устаревшие связи, видя их и при обучении, и при поиске.', '',
      f"Использовано {fit['q']} вопросов dev, {fit['t']} траектория, {fit['nodes']} пар кандидат–вопрос, из них {fit['positive']} положительных. Первая модель получает 27 стандартных признаков по точному графу, вторая — те же 27 по нарастающему. Третьей доступны 33 признака, включая шесть разностей между статистиками соседей перед отзывом и после. Параметры классификатора, веса классов и DenseFT-ранги зафиксированы до применения к тесту. Смесь обучающих и тестовых траекторий исключена. Предшествующие агрегаты ISETrace были известны до постановки сравнения.", '',
      f"Основная панель включает {g['q']} вопросов на {g['t']} траекториях после исключения старого структурного пилота. Результат относится к нахождению всех размеченных исходных фрагментов в первых 2048 токенах. Для каждой выбранной группы записей опубликованный span scorer сверялся с независимым пересчётом объединения интервалов.",'',
      '| Модель и состояние графа | Полное покрытие | Доля | Среднее покрытие | Токенов в среднем |','|---|---:|---:|---:|---:|', *[table_line(x,k,g) for k,x in labels.items()], '',
      f"Основной парный контраст отдельно обученных моделей exact против append дал {describe(g,'exact/exact','append/append')}. Изменение относительно одного замороженного читателя оценивается сопоставлением с результатом {describe(g,'r20/exact','r20/append')} у прежней R20-модели. Сами позиции, выбранные прежней моделью на двух графах, точно воспроизведены для всех 2000 тестовых запросов.",'',
      f"Передача шести дополнительных признаков отозванных связей относительно модели с доступом только к exact дала {describe(g,'dual/both','exact/exact')}. Обнуление этих шести признаков при той же обученной модели меняет долю полностью покрытых вопросов на {describe(g,'dual/both','dual/zero')} в пользу первого члена при положительном значении. Сравнения дополнительных вариантов разведочные.",'',
      'Доверительные интервалы получены парным bootstrap по целым траекториям. Повторные вопросы по одной истории остаются в одной группе. Преимущество под собственной обученной моделью оценивает пользу от выбора семантики хранения в данном протоколе. Эти данные сами по себе не доказывают рост качества ответов агента или превосходство над опубликованным многосидовым R-GCN.', '']
    if (D/'decomposition.json').exists():
        zz=read('decomposition.json')['panels']
        parts=zz['all']['estimates']
        lines+=['## Отдельные вклады состояния чтения и обучения', '',
            'После расчёта основной таблицы мы разложили диагональное различие exact/exact против append/append на два слагаемых. Сначала считаем эффект замены режима чтения при каждой из двух замороженных моделей и усредняем эти два контраста. Затем усредняем эффект замены обученной модели в двух фиксированных состояниях хранения. Сумма равна разности диагоналей в каждой строке. Такая симметричная алгебра позволяет измерить влияние состояния хранения даже при разной силе эффекта для разных моделей.', '',
            f"Усреднённый вклад режима чтения составил {parts['read_state']['pp']:+.2f} п.п., а режима обучения {parts['fit_state']['pp']:+.2f} п.п. Их сумма составляет наблюдаемые +2,82 п.п. Среди {zz['no_retired_edges']['n']} вопросов на {zz['no_retired_edges']['t']} траекториях без отозванных связей замена графа при фиксированной модели дала ровно нулевой эффект. Среди {zz['retired_edge_present']['n']} вопросов с такими связями изменение режима чтения дало {zz['retired_edge_present']['estimates']['read_state']['pp']:+.2f} п.п. Веса этой декомпозиции определены соглашением о равном вкладе двух путей. [Разности и кластерные интервалы](decomposition.json)",'']
    if (D/'extra-results.json').exists():
        e=read('extra-results.json')['novel']
        lines+=['## Траектории вне обучающей выборки', '',f"Во внешней по отношению к 500 dev-вопросам панели {e['q']} вопросов на {e['t']} траектории. Она принадлежит исходному набору ISETrace. Отдельно обученные читатели exact и append дали соответственно {e['means']['exact/exact']['hits']}/{e['q']} и {e['means']['append/append']['hits']}/{e['q']}. Парное различие {describe(e,'exact/exact','append/append')}. Для модели с разностями получено {e['means']['dual/both']['hits']}/{e['q']}. Объём панели ограничивает точность вывода.",'']
    else:
        lines+=['Дополнительная панель зависит от запечатанных DenseFT-рангов для дополнительных 80 dev-вопросов. В этом снимке основная таблица рассчитана по официальному тесту.','']
    lines+=['[Методика и воспроизведение](REPRODUCE_RU.md) · [Сводные метрики](test-results.json) · [Парные исходы](test-outcomes.json.gz) · [Материалы ISETrace](https://github.com/xiaoqi-7/GraphMemory)']
    (D/'REPORT_RU.md').write_text('\n'.join(lines)+'\n',encoding='utf8')
if __name__=='__main__':main()

